// Performs an SDP query on the target device.
//
// target: The target to message when the SDP query is complete
//
// # Return Value
//
// Returns kIOReturnSuccess if the SDP query was successfully started.
//
// # Discussion
//
// As a result of this call, a baseband connection will be built to the device
// (if not already connected). Then, an L2CAP channel will be opened to the
// SDP server on the device. At that point, a Service Search Attribute request
// will be issued with a UUID of 0x0100 (L2CAP) and an attribute range of
// 0x0000 - 0xffff specified. This will cause the SDP server to return all
// attributes of all L2CAP-derived services on the device. The results
// essentially encompass all services on the device. This function is always
// asynchronous. If a target is specified, when the SDP query is complete (or
// an error is encountered), the method -sdpQueryComplete:status: will be
// called on the given target. If no target is specified, the request is still
// asynchronous, but no callback will be made. That can be useful if the
// client has registered for SDP service changed notifications.
//
// See: https://developer.apple.com/documentation/IOBluetooth/IOBluetoothDevice/performSDPQuery(_:)
func (b IOBluetoothDevice) PerformSDPQuery(target objectivec.IObject) kernel.IOReturn {
	rv := objc.Send[kernel.IOReturn](b.ID, objc.Sel("performSDPQuery:"), target)
	return kernel.IOReturn(rv)
}

// Performs an SDP query on the target device with the specified service
// UUIDs.
//
// target: The target to message when the SDP query is complete
//
// uuidArray: An array of IOBluetoothSDPUUID objects for each service the caller is
// interested in
//
// # Return Value
//
// Returns kIOReturnSuccess if the SDP query was successfully started.
//
// # Discussion
//
// As a result of this call, a baseband connection will be built to the device
// (if not already connected). Then, an L2CAP channel will be opened to the
// SDP server on the device. At that point, a Service Search Attribute request
// will be issued for each service UUID specified in the UUID array.
//
// This function is always asynchronous. If a target is specified, when the
// SDP query is complete (or an error is encountered), the method
// -sdpQueryComplete:status: will be called on the given target. If no target
// is specified, the request is still asynchronous, but no callback will be
// made. That can be useful if the client has registered for SDP service
// changed notifications.
//
// See: https://developer.apple.com/documentation/IOBluetooth/IOBluetoothDevice/performSDPQuery(_:uuids:)
func (b IOBluetoothDevice) PerformSDPQueryUuids(target objectivec.IObject, uuidArray foundation.INSArray) kernel.IOReturn {
	rv := objc.Send[kernel.IOReturn](b.ID, objc.Sel("performSDPQuery:uuids:"), target, uuidArray)
	return kernel.IOReturn(rv)
}

