// # Return Value
//
// Returns an IOBluetoothUserNotification representing the outstanding device
// disconnect notification. To unregister the notification, call -unregister
// of the returned IOBluetoothUserNotification object. If an error is
// encountered creating the notification, nil is returned.
//
// # Discussion
//
// The given selector will be called on the target observer when the target
// device’s connection is closed. The selector should contain two arguments.
// The first is the user notification object. The second is the
// IOBluetoothDevice that was disconnected.
//
// See: https://developer.apple.com/documentation/IOBluetooth/IOBluetoothDevice/register(forDisconnectNotification:selector:)
func (b IOBluetoothDevice) RegisterForDisconnectNotificationSelector(observer objectivec.IObject, inSelector objc.SEL) IIOBluetoothUserNotification {
	rv := objc.Send[objc.ID](b.ID, objc.Sel("registerForDisconnectNotification:selector:"), observer, inSelector)
	return IOBluetoothUserNotificationFromID(rv)
}

// Issues a remote name request to the target device.
//
// target: The target to message when the remote name request is complete
//
// # Return Value
//
// Returns kIOReturnSuccess if the remote name request was successfully issued
// (and if synchronous, if the request completed successfully).
//
// # Discussion
//
// If a target is specified, the request is asynchronous and on completion of
// the request, the method
//
// - (void)remoteNameRequestComplete:(IOBluetoothDevice *)device
// status:(IOReturn)status;
//
// will be called on the specified target. If no target is specified, the
// request is made synchronously and won’t return until the request is
// complete. This call with operate with the default page timeout value. If a
// different page timeout value is desired, the method
// -remoteNameRequest:withPageTimeout: should be used instead.
//
// See: https://developer.apple.com/documentation/IOBluetooth/IOBluetoothDevice/remoteNameRequest(_:)
func (b IOBluetoothDevice) RemoteNameRequest(target objectivec.IObject) kernel.IOReturn {
	rv := objc.Send[kernel.IOReturn](b.ID, objc.Sel("remoteNameRequest:"), target)
	return kernel.IOReturn(rv)
}

// Issues a remote name request to the target device.
//
// target: The target to message when the remote name request is complete
//
// pageTimeoutValue: The page timeout value to use for this call
//
// # Return Value
//
// Returns kIOReturnSuccess if the remote name request was successfully issued
// (and if synchronous, if the request completed successfully).
//
// # Discussion
//
// If a target is specified, the request is asynchronous and on completion of
// the REMOTE_NAME_REQUEST command, the method
// -remoteNameRequestComplete:status:name: will be called on the specified
// target. If no target is specified, the request is made synchronously and
// won’t return until the request is complete.
//
// NOTE: This method is only available in macOS 10.2.7 (Bluetooth v1.3) or
// later.
//
// See: https://developer.apple.com/documentation/IOBluetooth/IOBluetoothDevice/remoteNameRequest(_:withPageTimeout:)
func (b IOBluetoothDevice) RemoteNameRequestWithPageTimeout(target objectivec.IObject, pageTimeoutValue BluetoothHCIPageTimeout) kernel.IOReturn {
	rv := objc.Send[kernel.IOReturn](b.ID, objc.Sel("remoteNameRequest:withPageTimeout:"), target, pageTimeoutValue)
	return kernel.IOReturn(rv)
}

// Removes the target device from the user’s favorite devices list.
//
// # Return Value
//
// Returns kIOReturnSuccess if the device was successfully removed from the
// user’s list of favorite devices.
//
// # Discussion
//
// NOTE: This method is only available in macOS 10.2.4 (Bluetooth v1.1) or
// later.
//
// See: https://developer.apple.com/documentation/IOBluetooth/IOBluetoothDevice/removeFromFavorites()
func (b IOBluetoothDevice) RemoveFromFavorites() kernel.IOReturn {
	rv := objc.Send[kernel.IOReturn](b.ID, objc.Sel("removeFromFavorites"))
	return kernel.IOReturn(rv)
}

// Requests that the existing baseband connection be authenticated.
//
// # Return Value
//
// Returns kIOReturnSuccess if the connection has been successfully been
// authenticated. Returns an error if authentication fails or no baseband
// connection exists.
//
// # Discussion
//
// In order to authenticate a baseband connection, a link key needs to be
// generated as a result of the pairing process. This call will synchronously
// initiate the pairing process with the target device and not return until
// the authentication process is complete. This API will be updated to allow
// for asynchronous operation.
//
// See: https://developer.apple.com/documentation/IOBluetooth/IOBluetoothDevice/requestAuthentication()
func (b IOBluetoothDevice) RequestAuthentication() kernel.IOReturn {
	rv := objc.Send[kernel.IOReturn](b.ID, objc.Sel("requestAuthentication"))
	return kernel.IOReturn(rv)
}

// Get the RSSI device (if connected), above or below the golden range. If the
// RSSI is within the golden range, a value of 0 is returned. For the actual
// RSSI value, use getRawRSSI. For more information, see the Bluetooth 4.0
// Core Specification.
//
// # Return Value
//
// Returns the RSSI of the device. If the value cannot be read (e.g. the
// device is disconnected), a value of +127 will be returned.
//
// See: https://developer.apple.com/documentation/IOBluetooth/IOBluetoothDevice/rssi()
func (b IOBluetoothDevice) RSSI() BluetoothHCIRSSIValue {
	rv := objc.Send[BluetoothHCIRSSIValue](b.ID, objc.Sel("RSSI"))
	return BluetoothHCIRSSIValue(rv)
}

// Send an echo request over the L2CAP connection to a remote device.
//
// data: (Void *) - Pointer to buffer to send.
//
// length: (UInt16) - Length of the buffer to send
//
// # Return Value
//
// Returns kIOReturnSuccess if the echo request was able to be sent.
//
// # Discussion
//
// The current implementation returns when the request has been sent, but does
// not indicate when a response is received. Also, the baseband connection
// must be up for the echo request to be sent. In the future, this method will
// also open the connection if necessary. The API will be updated to allow the
// client to be informed when the echo response has been received (both
// synchronously and asynchronously).
//
// See: https://developer.apple.com/documentation/IOBluetooth/IOBluetoothDevice/sendL2CAPEchoRequest(_:length:)
func (b IOBluetoothDevice) SendL2CAPEchoRequestLength(data unsafe.Pointer, length uint16) kernel.IOReturn {
	rv := objc.Send[kernel.IOReturn](b.ID, objc.Sel("sendL2CAPEchoRequest:length:"), data, length)
	return kernel.IOReturn(rv)
}

// Sets the connection supervision timeout.
//
// timeout: A client-supplied link supervision timeout value to use to monitor the
// connection. The timeout value should be specified in slots, so you can use
// the BluetoothGetSlotsFromSeconds macro to get the proper value. e.g.
// BluetoothGetSlotsFromSeconds( 5.0 ) will give yield the proper number of
// slots (8000) for 5 seconds.
//
// # Return Value
//
// Returns kIOReturnSuccess if it was possible to set the connection
// supervision timeout.
//
// # Discussion
//
// NOTE: This method is only available in macOS 10.5 (Bluetooth v2.0) or
// later.
//
// See: https://developer.apple.com/documentation/IOBluetooth/IOBluetoothDevice/setSupervisionTimeout(_:)
func (b IOBluetoothDevice) SetSupervisionTimeout(timeout uint16) kernel.IOReturn {
	rv := objc.Send[kernel.IOReturn](b.ID, objc.Sel("setSupervisionTimeout:"), timeout)
	return kernel.IOReturn(rv)
}

// Gets an array of the user’s favorite devices.
//
// # Return Value
//
// Returns an array of device objects representing the user’s favorite
// devices. If the user has no favorites, nil is returned.
//
// # Discussion
//
// The resulting array contains IOBluetoothDevice objects.
//
// NOTE: This method is only available in macOS 10.2.4 (Bluetooth v1.1) or
// later.
//
// See: https://developer.apple.com/documentation/IOBluetooth/IOBluetoothDevice/favoriteDevices()
func (_IOBluetoothDeviceClass IOBluetoothDeviceClass) FavoriteDevices() foundation.INSArray {
	rv := objc.Send[objc.ID](objc.ID(_IOBluetoothDeviceClass.class), objc.Sel("favoriteDevices"))
	return foundation.NSArrayFromID(rv)
}

// Gets an array of all of the paired devices on the system.
//
// # Return Value
//
// Returns an array of device objects for all of the paired devices on the
// system. If there are no paired devices, nil is returned.
//
// # Discussion
//
// The resulting array contains IOBluetoothDevice objects. The paired devices
// are currently NOT stored per user, so this is all devices paired by any
// user.
//
// NOTE: This method is only available in macOS 10.2.5 (Bluetooth v1.2) or
// later.
//
// See: https://developer.apple.com/documentation/IOBluetooth/IOBluetoothDevice/pairedDevices()
func (_IOBluetoothDeviceClass IOBluetoothDeviceClass) PairedDevices() foundation.INSArray {
	rv := objc.Send[objc.ID](objc.ID(_IOBluetoothDeviceClass.class), objc.Sel("pairedDevices"))
	return foundation.NSArrayFromID(rv)
}

// Gets an array of recently used Bluetooth devices.
//
// numDevices: The number of devices to return.
//
// # Return Value
//
// Returns an array of device objects recently used by the system. If no
// devices have been accessed, nil is returned.
//
// # Discussion
//
// The resulting array contains IOBluetoothDevice objects sorted in reverse
// chronological order. The most recently accessed devices are first. If the
// numDevices parameter is 0, all devices accessed by the system are returned.
// If numDevices is non-zero, only the most recent devices are returned.
//
// NOTE: This method is only available in macOS 10.2.4 (Bluetooth v1.1) or
// later.
//
// See: https://developer.apple.com/documentation/IOBluetooth/IOBluetoothDevice/recentDevices(_:)
func (_IOBluetoothDeviceClass IOBluetoothDeviceClass) RecentDevices(numDevices uint64) foundation.INSArray {
	rv := objc.Send[objc.ID](objc.ID(_IOBluetoothDeviceClass.class), objc.Sel("recentDevices:"), numDevices)
	return foundation.NSArrayFromID(rv)
}

// Allows a client to register for device connect notifications for any
// connection.
//
// observer: Target observer object
//
// inSelector: Selector to be sent to the observer when a new connection is made
//
// # Return Value
//
// Returns an IOBluetoothUserNotification representing the outstanding device
// connect notification. To unregister the notification, call -unregister on
// the returned IOBluetoothUserNotification object. If an error is encountered
// creating the notification, nil is returned. The returned
// IOBluetoothUserNotification object will be valid for as long as the
// notification is registered. It is not necessary to retain the result. Once
// -unregister is called on it, it will no longer be valid.
//
// # Discussion
//
// The given selector will be called on the target observer whenever any
// device connection is made. The selector should accept two arguments. The
// first is the user notification object. The second is the device that was
// connected.
//
// See: https://developer.apple.com/documentation/IOBluetooth/IOBluetoothDevice/register(forConnectNotifications:selector:)
func (_IOBluetoothDeviceClass IOBluetoothDeviceClass) RegisterForConnectNotificationsSelector(observer objectivec.IObject, inSelector objc.SEL) IOBluetoothUserNotification {
	rv := objc.Send[objc.ID](objc.ID(_IOBluetoothDeviceClass.class), objc.Sel("registerForConnectNotifications:selector:"), observer, inSelector)
	return IOBluetoothUserNotificationFromID(rv)
}

