// Gets an array of service records for the device.
//
// # Return Value
//
// Returns an array of service records for the device if an SDP query has been
// performed. If no SDP query has been performed, nil is returned.
//
// # Discussion
//
// The resulting array contains IOBluetoothSDPServiceRecord objects. The
// service records are only present if an SDP query has been done on the
// target object. This can be determined by calling -getLastServicesUpdate. It
// will return the last date/time of the SDP query. To initiate an SDP query
// on a device, use -performSDPQuery: as defined above.
//
// Instead of allowing individual clients to query for different services and
// service attributes, the system request all of the device’s services and
// service attributes.
//
// See: https://developer.apple.com/documentation/IOBluetooth/IOBluetoothDevice/services
func (b IOBluetoothDevice) Services() foundation.INSArray {
	rv := objc.Send[objc.ID](b.ID, objc.Sel("services"))
	return foundation.NSArrayFromID(objc.ID(rv))
}
